mapper.insert:
/* apiQuickReg.savTmplt */

  SELECT CURRVAL('koa_tb_api_quick_tmplt_tmplt_no_seq')

INSERT INTO KOA_TB_API_QUICK_TMPLT
(
   TMPLT_NM
  ,TMPLT_DESC
  ,API_CLASS
  ,MTH_TYPE_CD
  ,CNT_TYPE_CD
  ,PATH_PATTERN
  ,DFLT_PARAM_JSON
  ,DFLT_FIELD_JSON
  ,TMPLT_YAML
  ,SORT_ODRG
  ,USE_YN
  ,REG_DT
  ,REGR
)
VALUES
(
   #{tmpltNm}
  ,#{tmpltDesc}
  ,#{apiClass}
  ,#{mthTypeCd}
  ,NULLIF(#{cntTypeCd}, '')
  ,#{pathPattern}
  ,#{dfltParamJson}
  ,#{dfltFieldJson}
  ,#{tmpltYaml}
  ,COALESCE((SELECT MAX(SORT_ODRG) + 1 FROM KOA_TB_API_QUICK_TMPLT), 1)
  ,'Y'
  ,NOW()
  ,#{regr}
)

mapper.update:
/* apiQuickReg.updTmplt */
UPDATE KOA_TB_API_QUICK_TMPLT
SET
   TMPLT_NM        = #{tmpltNm}
  ,TMPLT_DESC      = #{tmpltDesc}
  ,API_CLASS       = #{apiClass}
  ,MTH_TYPE_CD     = #{mthTypeCd}
  ,CNT_TYPE_CD     = NULLIF(#{cntTypeCd}, '')
  ,PATH_PATTERN    = #{pathPattern}
  ,DFLT_PARAM_JSON = #{dfltParamJson}
  ,DFLT_FIELD_JSON = #{dfltFieldJson}
  ,TMPLT_YAML      = #{tmpltYaml}
  ,AMD_DT          = NOW()
  ,AMDR            = #{amdr}
WHERE TMPLT_NO = #{tmpltNo}::integer

mapper.insert:
/* apiQuickReg.savApiSpc */
SELECT CURRVAL('koa_tb_api_spc_api_spc_no_seq')
INSERT INTO KOA_TB_API_SPC ( API_SPC_NO ,API_SPC_ID ,VER ,API_NM ,API_DESC ,AUT_ID ,SYS_ID ,HOST ,BAS_PATH ,YAML_FILE_PATH ,YAML_FILE_NM ,REG_STTUS_CD ,REG_DT ,REGR ,AMD_DT ,AMDR ,DEL_YN ,SHOW_YN ,API_CLASS ,BSTGW_YN ,API_VERI_BASEURL ) SELECT NID.ID ,CONCAT('QUICK-', NID.ID) ,#{ver} ,#{apiNm} ,#{apiDesc} ,#{autId}::integer ,#{sysId} ,#{host} ,#{basPath} ,'/quickreg' ,CONCAT(#{apiNm}::text, '.yaml') ,'APIREG1020' ,NOW() ,#{regr} ,NOW() ,#{amdr} ,'N' ,'N' ,#{apiClass} ,#{bstgwYn} ,#{apiVeriBaseurl} FROM ( SELECT NEXTVAL('koa_tb_api_spc_api_spc_no_seq') AS ID ) NID

/* apiQuickReg.savApiCtgry */
SELECT CURRVAL('koa_tb_api_ctgry_api_ctgry_no_seq')
INSERT INTO KOA_TB_API_CTGRY ( API_SPC_NO ,CTGRY_NM ,SORT_ODRG ,DEL_YN ,REG_DT ,REGR ,AMD_DT ,AMDR ) VALUES ( #{apiSpcNo}::integer ,#{ctgryNm} ,1 ,'N' ,NOW() ,#{regr} ,NOW() ,#{amdr} )

/* apiQuickReg.savApiDef */
SELECT CURRVAL('koa_tb_api_def_api_no_seq')
INSERT INTO KOA_TB_API_DEF ( API_SPC_NO ,API_NM ,API_CTGRY_NO ,API_PATH ,METHOD_CD ,API_DESC ,REG_DT ,REGR ,AMD_DT ,AMDR ,USE_YN ,API_GUBUN ,API_HANDLER_CD ,PROVIDER_SEQ ) VALUES ( #{apiSpcNo}::integer ,#{apiNm} ,#{apiCtgryNo}::integer ,#{apiPath} ,#{methodCd} ,#{apiDesc} ,NOW() ,#{regr} ,NOW() ,#{amdr} ,'Y' ,#{apiClass} ,NULLIF(#{apiHandlerCd}, '') ,NULLIF(#{providerSeq}, '')::integer )

/* apiQuickReg.savApiParam */

  SELECT CURRVAL('koa_tb_api_param_param_no_seq')

INSERT INTO KOA_TB_API_PARAM
(
   API_NO
  ,PARAM_TYPE_CD
  ,SORT_ODRG
  ,PARAM_NM
  ,DATA_TYPE_CD
  ,PARAM_DESC
  ,PARAM_LOC
  ,REQUIRED
  ,PRNTS_PARAM_NO
  ,OBJ_NO
  ,OBJ_ODRG
  ,EXAM
  ,PERSONAL_DATA
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
)
VALUES
(
   #{apiNo}::integer
  ,#{paramTypeCd}
  ,#{sortOdrg}::integer
  ,#{paramNm}
  ,#{dataTypeCd}
  ,#{paramDesc}
  ,#{paramLoc}
  ,#{required}
  ,NULLIF(#{prntsParamNo}, '')::integer
  ,NULLIF(#{objNo}, '')::integer
  ,NULLIF(#{objOdrg}, '')::integer
  ,#{exam}
  ,#{personalData}
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{regr}
)
